import java.util.*;
import java.io.*;

public class Main {
    static final int MOD_CONST = 1000000007;
    static List<List<Integer>> group_vectors = new ArrayList<>();
    static long[] popcount_array;
    static long[] prob_p;
    static long[] prob_a;
    static Map<Long, Long>[] dp_map;
    static int n_size;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n_size = Integer.parseInt(br.readLine().trim());

        for (int i = 0; i <= n_size; i++) {
            group_vectors.add(new ArrayList<>());
        }

        int total_states = 1 << n_size;
        popcount_array = new long[total_states];
        prob_p = new long[n_size];
        prob_a = new long[n_size];

        for (int idx_i = 0; idx_i < total_states; idx_i++) {
            int count = Integer.bitCount(idx_i);
            popcount_array[idx_i] = group_vectors.get(count).size();
            group_vectors.get(count).add(idx_i);
        }

        dp_map = new HashMap[n_size + 1];
        for (int i = 0; i <= n_size; i++) {
            dp_map[i] = new HashMap<>();
        }

        // Initialize dp_map[0][1] = 1
        dp_map[0].put(1L, 1L);

        for (int idx_i = 0; idx_i < n_size; idx_i++) {
            String[] probStrs = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n_size; j++) {
                long p = Long.parseLong(probStrs[j]);
                prob_p[j] = p * 570000004L % MOD_CONST;
            }

            for (Map.Entry<Long, Long> stateEntry : dp_map[idx_i].entrySet()) {
                long state = stateEntry.getKey();
                long count = stateEntry.getValue();

                Arrays.fill(prob_a, 0);
                for (int m : group_vectors.get((int) popcount_array[(int) state])) {
                    if (((state >> (int) popcount_array[m]) & 1) != 0) {
                        for (int j = 0; j < n_size; j++) {
                            if (((m >> j) & 1) == 0) {
                                prob_a[j] |= (1L << popcount_array[m | (1 << j)]);
                            }
                        }
                    }
                }

                for (int msk = 0; msk < (1 << n_size); msk++) {
                    long val_X = 1;
                    long val_M = 0;
                    for (int j = 0; j < n_size; j++) {
                        if (((msk >> j) & 1) != 0) {
                            val_M |= prob_a[j];
                            val_X = (val_X * prob_p[j]) % MOD_CONST;
                        } else {
                            val_X = (val_X * (MOD_CONST - prob_p[j] + 1)) % MOD_CONST;
                        }
                    }
                    long new_state = val_M;
                    long prev = dp_map[idx_i + 1].getOrDefault(new_state, 0L);
                    long new_val = (prev + count * val_X) % MOD_CONST;
                    dp_map[idx_i + 1].put(new_state, new_val);
                }
            }
        }

        System.out.println(dp_map[n_size].getOrDefault(1L, 0L));
    }
}
